"""Synthetic oracle regressions; these fixtures are not native observations."""

import copy
import importlib.util
from pathlib import Path
import unittest
from unittest.mock import patch


SPEC = importlib.util.spec_from_file_location("pi_oracle", Path(__file__).with_name("pi_oracle.py"))
oracle = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(oracle)
EXPECTED = b"3141592653\t:10\n5897932384\t:20\n6264338   \t:27\n"


def synthetic_rows():
    # Independently generate input rows with integer divmod; expected stdout is
    # a fixed corpus value, never generated by the checker under test.
    q, r, t, k, emitted = 1, 0, 1, 1, 0
    rows = []
    pair = 0
    while emitted < 27:
        pair += 1
        values = (3 * q + r, 4 * q + r)
        quotients = [divmod(value, t)[0] for value in values]
        for site, value, quotient in zip((15, 16), values, quotients):
            rows.append([pair, site, q, r, t, k, emitted, value, t, quotient])
        if quotients[0] != quotients[1]:
            old_q = q
            q *= k
            r = (2 * old_q + r) * (2 * k + 1)
            t *= 2 * k + 1
            k += 1
        else:
            r = (r - quotients[0] * t) * 10
            q *= 10
            emitted += 1
    return rows


def encode(rows):
    return oracle.HEADER + b"".join(b"\t".join(str(value).encode("ascii") for value in row)
                                    + b"\n" for row in rows)


class PiOracleTests(unittest.TestCase):
    def setUp(self):
        self.rows = synthetic_rows()
        self.trace = encode(self.rows)

    def validate(self, trace=None, **changes):
        args = {"stdout": EXPECTED, "stderr": b"", "exit_status": 0,
                "trace": self.trace if trace is None else trace, "expected": EXPECTED}
        args.update(changes)
        return oracle.validate(**args)

    def test_complete_synthetic_recurrence_and_reference(self):
        self.assertEqual(self.rows[:4], [
            [1, 15, 1, 0, 1, 1, 0, 3, 1, 3],
            [1, 16, 1, 0, 1, 1, 0, 4, 1, 4],
            [2, 15, 1, 6, 3, 2, 0, 9, 3, 3],
            [2, 16, 1, 6, 3, 2, 0, 10, 3, 3],
        ])
        result = self.validate()
        self.assertEqual(result["emitted_digits"], 27)
        self.assertEqual(result["facade_calls"], len(self.rows))
        self.assertEqual(result["call_pairs"], result["equal_branches"] + result["unequal_branches"])
        for call in result["beyond_u64_pair"]["calls"]:
            self.assertTrue(call["beyond_u64_operands"])
            self.assertGreater(max(abs(int(call["numerator"])), abs(int(call["denominator"]))),
                               (1 << 64) - 1)
        for gate in ("native_process_verified", "machine_division_count_established",
                     "source_work_qualified", "runtime_source_equivalence_proven",
                     "canonical_source_count_qualified", "full_timing_qualified", "chart_admission"):
            self.assertIs(result[gate], False)

    def test_floor_semantics_do_not_use_truncation(self):
        oracle.check_quotient(-7, 3, -3)
        oracle.check_quotient(-6, 3, -2)
        oracle.check_quotient(7, 3, 2)
        with self.assertRaisesRegex(AssertionError, "Floor quotient"):
            oracle.check_quotient(-7, 3, -2)
        for denominator in (0, -3):
            with self.subTest(denominator=denominator), self.assertRaises(AssertionError):
                oracle.check_quotient(7, denominator, 2)

    def test_every_state_field_is_bound_on_both_calls(self):
        for row_index in (2, 3):
            for field in range(2, 7):
                rows = copy.deepcopy(self.rows)
                rows[row_index][field] += 1
                with self.subTest(row=row_index, field=field), self.assertRaisesRegex(AssertionError, "state"):
                    self.validate(encode(rows))

    def test_each_full_operand_and_quotient_is_checked(self):
        for row_index in (0, 1):
            for field in (7, 8, 9):
                rows = copy.deepcopy(self.rows)
                rows[row_index][field] += 1
                with self.subTest(row=row_index, field=field), self.assertRaises(AssertionError):
                    self.validate(encode(rows))

    def test_pair_sequence_and_source_sites(self):
        for row_index, field, value in ((0, 0, 0), (2, 0, 1), (0, 1, 16), (1, 1, 15)):
            rows = copy.deepcopy(self.rows)
            rows[row_index][field] = value
            with self.subTest(row=row_index, field=field), self.assertRaisesRegex(AssertionError, "call/site"):
                self.validate(encode(rows))

    def test_missing_duplicate_and_extra_pairs(self):
        for rows in (self.rows[:-2], self.rows[2:], self.rows[:2] + self.rows,
                     self.rows + self.rows[-2:]):
            with self.subTest(length=len(rows)), self.assertRaises(AssertionError):
                self.validate(encode(rows))

    def test_incomplete_call_and_row(self):
        for trace in (encode(self.rows[:-1]), self.trace[:-1], oracle.HEADER):
            with self.subTest(length=len(trace)), self.assertRaises(AssertionError):
                self.validate(trace)

    def test_decimal_spellings_and_field_count_are_strict(self):
        lines = self.trace.splitlines(keepends=True)
        for value in (b"+1", b"01", b"-0", b"1.0", b"1e0", b" 1", b"1\r", b"\xff"):
            fields = lines[2].rstrip(b"\n").split(b"\t")
            fields[0] = value
            with self.subTest(value=value), self.assertRaises(AssertionError):
                self.validate(b"".join(lines[:2]) + b"\t".join(fields) + b"\n" + b"".join(lines[3:]))
        for suffix in (b"\t0", b"\t", b"\n"):
            with self.subTest(suffix=suffix), self.assertRaises(AssertionError):
                self.validate(b"".join(lines[:2]) + lines[2][:-1] + suffix + b"\n" + b"".join(lines[3:]))

    def test_header_and_complete_byte_limit(self):
        with self.assertRaisesRegex(AssertionError, "header"):
            self.validate(self.trace.replace(b"\t27\n", b"\t26\n", 1))
        with self.assertRaisesRegex(AssertionError, "byte limit"):
            self.validate(self.trace + b"x" * oracle.MAX_TRACE_BYTES)

    def test_beyond_u64_witness_is_required(self):
        # Raising only the test threshold keeps the valid recurrence intact,
        # demonstrating that its printed output cannot replace the witness.
        maximum = max(abs(row[field]) for row in self.rows for field in (7, 8))
        with patch.object(oracle, "U64_MAX", maximum), self.assertRaisesRegex(AssertionError, "beyond-u64"):
            self.validate()

    def test_reference_and_actual_output_are_independently_bound(self):
        for changes in ({"stdout": EXPECTED[:-1]}, {"stdout": EXPECTED + b"\n"},
                        {"expected": EXPECTED.replace(b"314", b"315", 1)},
                        {"stdout": EXPECTED[:-1], "expected": EXPECTED[:-1]}):
            with self.subTest(changes=changes), self.assertRaises(AssertionError):
                self.validate(**changes)

    def test_exit_stderr_and_stream_types(self):
        for changes in ({"exit_status": 1}, {"exit_status": False}, {"stderr": b"warning\n"},
                        {"stdout": bytearray(EXPECTED)}, {"expected": EXPECTED.decode("ascii")},
                        {"trace": bytearray(self.trace)}):
            with self.subTest(changes=changes), self.assertRaises(AssertionError):
                self.validate(**changes)


if __name__ == "__main__":
    unittest.main()
